INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, 0, "シズルさまにエリコさま、\nどうかされたのですか？", 0, 19050041, 10, 0.5, 11, 107611, 905, 0);
