INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, 0, "はい、そこの流れてくるおねーさん\nたい焼きいかがかにゃ？", 0, 19440025, 8, 1, 11, 107911, 944, 0);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", "", "", 19440026, "", "", 91, 0, 944, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("44_yukari_notice_loop", 0.1, "44_yukari_notice", 0.2, 19440027, 0, "", 3, 126811, 944, 1);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", "cmn_boat_idle", 0.2, 19440028, 1, "", 3, 2, 944, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0, "", "vo_fpc_30403", "", 19440029, "", "", 21, "vo_fpc", 944, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, 0, "あら、タマキさんじゃない。\nこんなところで何やってるの？", 0, 19440030, 10, 1, 11, 126811, 944, 0);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", "", "", 19440031, "", "", 91, 0, 944, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0, "", "vo_fpc_30404", "", 19440032, "", "", 21, "vo_fpc", 944, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, 0, "なんだ、ユカリだったかにゃ。\n何ってもちろん商売にゃ！", 0, 19440033, 10, 1, 11, 107911, 944, 0);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", "", "", 19440034, "", "", 91, 0, 944, "");
