INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0, "", "vo_fpc_30405", "", 19440037, "", "", 21, "vo_fpc", 944, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, 0, "こんなに人がいっぱいいる商機、\n見逃すわけにはいかないにゃ！", 0, 19440038, 10, 1, 11, 107911, 944, 0);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", "", "", 19440039, "", "", 91, 0, 944, "");
