INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0, "", "vo_fpc_30406", "", 19440042, "", "", 21, "vo_fpc", 944, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, 0, "それ、アキノさんの許可とってるの？\nもし無許可だったら怒られるわよ？", 0, 19440043, 7, 1, 11, 126811, 944, 0);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", "", "", 19440044, "", "", 91, 0, 944, "");
