INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, 0, "大丈夫にゃ。バレないように…\nってやばいにゃ！　見回りだにゃ！", 0, 19440046, 8, 0.5, 11, 107911, 944, 0);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", "", "", 19440047, "", "", 91, 0, 944, "");
