INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, 0, "無許可営業は取り締まり対象よ！\n待ちなさい！", 0, 19440062, 15, 0.5, 11, 108011, 944, 0);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", "", "", 19440063, "", "", 91, 19440058, 944, "");
